	@Test
	void abandonedPreparedFileIsIgnoredOnReopen(@TempDir(cleanup = CleanupMode.NEVER) Path root)
			throws Exception {
		Fixture fixture = fixture(root);
		Path orphan = fixture.directory.getParent().resolve(".synopsis.filters-abandoned.tmp");
		EstimatorSidecar failing = new EstimatorSidecar(fixture.location, fixture.directory,
				EstimatorSidecar.Channel.FILTER, (destination, temporary) -> {
					Files.copy(temporary, orphan);
					throw new IOException("injected failure before publication");
				});
		assertThrows(IOException.class, () -> failing.write(out -> out.writeUTF("old")));
		assertFalse(Files.exists(fixture.target, LinkOption.NOFOLLOW_LINKS));
		byte[] orphanBytes = Files.readAllBytes(orphan);
		assertTrue(orphanBytes.length > 72, "the abandoned artifact is a completed envelope");
		EstimatorSidecar reopened = new EstimatorSidecar(EstimatorPersistenceLocation.forStandalone(fixture.legacy),
				fixture.directory, EstimatorSidecar.Channel.FILTER);
		reopened.write(out -> out.writeUTF("new"));
		try (EstimatorSidecar.Payload payload = reopened.open()) {
			assertEquals("new", payload.input().readUTF());
			payload.verify();
		}
		assertArrayEquals(orphanBytes, Files.readAllBytes(orphan));
		assertArrayEquals(LEGACY, Files.readAllBytes(fixture.legacy));
	}

