	@ParameterizedTest
	@ValueSource(strings = { "checksum", "truncated", "oversized", "wrong-channel", "wrong-owner" })
	void invalidEnvelopeCannotBeAdoptedOrOverwritten(String kind,
			@TempDir(cleanup = CleanupMode.NEVER) Path root) throws Exception {
		Fixture fixture = fixture(root.resolve("one"));
		EstimatorSidecar filter = new EstimatorSidecar(fixture.location, fixture.directory,
				EstimatorSidecar.Channel.FILTER);
		if (kind.equals("checksum") || kind.equals("truncated") || kind.equals("oversized")) {
			filter.write(out -> out.writeUTF("valid"));
			byte[] valid = Files.readAllBytes(fixture.target);
			byte[] invalid = kind.equals("truncated") ? Arrays.copyOf(valid, valid.length - 1) : valid.clone();
			if (kind.equals("checksum"))
				invalid[invalid.length - 1] ^= 1;
			if (kind.equals("oversized"))
				ByteBuffer.wrap(invalid).putLong(32, Long.MAX_VALUE);
			Files.write(fixture.target, invalid, StandardOpenOption.TRUNCATE_EXISTING);
		} else if (kind.equals("wrong-channel")) {
			EstimatorSidecar leo = new EstimatorSidecar(fixture.location, fixture.directory,
					EstimatorSidecar.Channel.LEO);
			leo.write(out -> out.writeUTF("valid"));
			Files.copy(fixture.directory.resolveSibling("synopsis.leo"), fixture.target);
		} else {
			Fixture other = fixture(root.resolve("other"));
			EstimatorSidecar otherFilter = new EstimatorSidecar(other.location, other.directory,
					EstimatorSidecar.Channel.FILTER);
			otherFilter.write(out -> out.writeUTF("valid"));
			Files.copy(other.target, fixture.target);
		}
		byte[] original = Files.readAllBytes(fixture.target);
		assertThrows(IOException.class, () -> filter.write(out -> out.writeUTF("replacement")));
		assertArrayEquals(original, Files.readAllBytes(fixture.target));
		assertArrayEquals(LEGACY, Files.readAllBytes(fixture.legacy));
	}

